def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]

    total = v1 + v2 + v3
    count = 3

    if count == 0:
        return None

    average = total / count

    return {
        "value": average,
        "trace": {
            "values": [v1, v2, v3],
            "total": total,
            "count": count,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "currency"
            }
        }
    }
